// Import http and fs modules here
const http = require('http');
const fs = require('fs');

// Create the createServer function here
function createServer() {
  // Define PORT and ENVIRONMENT_STATUS constants here
  const PORT = process.env.PORT || 3000;
  const ENVIRONMENT_STATUS = process.env.NODE_ENV || 'development';

  // Create readiness check handler here
  const readinessHandler = (req, res) => {
    if (req.url === '/ready' && req.method === 'GET') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'ready', environment: ENVIRONMENT_STATUS }));
    }
  };

  // Create health check handler here
  const healthHandler = (req, res) => {
    if (req.url === '/health' && req.method === 'GET') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'healthy', timestamp: new Date().toISOString() }));
    }
  };

  // Create version endpoint handler here
  const versionHandler = (req, res) => {
    if (req.url === '/version' && req.method === 'GET') {
      const packageJson = JSON.parse(fs.readFileSync('./package.json', 'utf8'));
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ version: packageJson.version }));
    }
  };

  // Implement main request handler here
  const requestHandler = (req, res) => {
    readinessHandler(req, res);
    healthHandler(req, res);
    versionHandler(req, res);

    // Default 404 for unmatched routes
    if (!res.headersSent) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Not Found' }));
    }
  };

  // Create HTTP server instance here
  const server = http.createServer(requestHandler);

  // Start the server here
}

